<?php
require_once __DIR__ . '/includes/auth.php';
require_staff();
$pdo = db();
$q = trim((string)($_GET['q'] ?? ''));
$from = trim((string)($_GET['from'] ?? ''));
$to = trim((string)($_GET['to'] ?? ''));
$fromSql = $from !== '' ? $from . ' 00:00:00' : null;
$toSql = $to !== '' ? date('Y-m-d', strtotime($to . ' +1 day')) . ' 00:00:00' : null;
$where = [];
$params = [];
if ($fromSql) { $where[] = 'b.created_at >= ?'; $params[] = $fromSql; }
if ($toSql) { $where[] = 'b.created_at < ?'; $params[] = $toSql; }
if ($q !== '') { $where[] = '(b.case_no LIKE ? OR b.report_type LIKE ? OR b.incident_type LIKE ? OR b.complainant LIKE ? OR b.respondent LIKE ? OR b.location LIKE ?)'; for ($i=0;$i<6;$i++) $params[] = '%'.$q.'%'; }
$filterSql = $where ? ' WHERE '.implode(' AND ', $where) : '';
function report_rows(PDO $pdo, string $sql, array $params = []): array { $s=$pdo->prepare($sql); $s->execute($params); return $s->fetchAll(); }
$reportTypes = report_rows($pdo, "SELECT b.report_type,COUNT(*) total FROM blotters b{$filterSql} GROUP BY b.report_type ORDER BY total DESC", $params);
$statuses = report_rows($pdo, "SELECT b.status,COUNT(*) total FROM blotters b{$filterSql} GROUP BY b.status ORDER BY total DESC", $params);
$recent = report_rows($pdo, "SELECT b.case_no,b.report_type,b.incident_type,b.complainant,b.location,b.status,b.created_at FROM blotters b{$filterSql} ORDER BY b.created_at DESC LIMIT 100", $params);
$docWhere=[];$docParams=[];
if($fromSql){$docWhere[]='d.requested_at >= ?';$docParams[]=$fromSql;}
if($toSql){$docWhere[]='d.requested_at < ?';$docParams[]=$toSql;}
if($q!==''){$docWhere[]='(d.request_no LIKE ? OR d.document_type LIKE ? OR d.requester_name LIKE ? OR d.purpose LIKE ?)';for($i=0;$i<4;$i++)$docParams[]='%'.$q.'%';}
$docFilterSql=$docWhere?' WHERE '.implode(' AND ',$docWhere):'';
$docTypes=report_rows($pdo,"SELECT d.document_type,COUNT(*) total FROM document_requests d{$docFilterSql} GROUP BY d.document_type ORDER BY total DESC",$docParams);
$countStmt=$pdo->prepare("SELECT COUNT(*) FROM blotters b{$filterSql}");$countStmt->execute($params);$totalReports=(int)$countStmt->fetchColumn();
$countStmt=$pdo->prepare("SELECT COUNT(*) FROM document_requests d{$docFilterSql}");$countStmt->execute($docParams);$totalDocs=(int)$countStmt->fetchColumn();
$resolvedStmt=$pdo->prepare("SELECT COUNT(*) FROM blotters b{$filterSql} AND b.status='Resolved'");
if(!$where)$resolvedStmt=$pdo->prepare("SELECT COUNT(*) FROM blotters b WHERE b.status='Resolved'");$resolvedStmt->execute($params);$resolved=(int)$resolvedStmt->fetchColumn();
$feedbackCount=(int)$pdo->query('SELECT COUNT(*) FROM feedback')->fetchColumn();
$maxType=max(1,...array_map(fn($r)=>(int)$r['total'],$reportTypes));$maxDoc=max(1,...array_map(fn($r)=>(int)$r['total'],$docTypes));
$queryString=http_build_query(array_filter(['q'=>$q,'from'=>$from,'to'=>$to],fn($v)=>$v!==''));$exportSuffix=$queryString?'&'.$queryString:'';
$pageTitle='Reports & analytics';$activePage='reports';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Reports / Analytics desk</div><h1>Reports & analytics</h1><p>Search the report register, choose a date range, and export the filtered result.</p></div><div class="export-actions"><a class="secondary-button" href="report_export.php?format=pdf<?= h($exportSuffix) ?>">PDF</a><a class="secondary-button" href="report_export.php?format=csv<?= h($exportSuffix) ?>">CSV</a><a class="primary-button" href="report_export.php?format=word<?= h($exportSuffix) ?>">Word</a></div></section><form class="panel report-filter" method="get"><label>Search records<input name="q" value="<?= h($q) ?>" placeholder="Case, category, complainant, location"></label><label>From date<input type="date" name="from" value="<?= h($from) ?>"></label><label>To date<input type="date" name="to" value="<?= h($to) ?>"></label><div class="filter-actions"><button class="primary-button" type="submit">Apply filters</button><a class="secondary-button" href="reports.php">Clear</a></div></form><section class="report-meta panel"><div><span>Report period</span><strong><?= h($from?:'All time') ?><?= $to?' — '.h($to):'' ?></strong></div><div><span>Prepared by</span><strong><?= h(current_user()['full_name']) ?></strong></div><div><span>Designated signatory</span><strong>Hon. Roberto Reyes · Punong Barangay</strong></div><div><span>Matching records</span><strong><?= $totalReports ?> reports · <?= $totalDocs ?> documents</strong></div></section><div class="stats-grid"><div class="stat-card"><div class="stat-icon amber">▣</div><span class="stat-label">Total reports</span><strong><?= $totalReports ?></strong><small>Filtered cases</small></div><div class="stat-card"><div class="stat-icon blue">▤</div><span class="stat-label">Documents requested</span><strong><?= $totalDocs ?></strong><small>Filtered requests</small></div><div class="stat-card"><div class="stat-icon mint">✓</div><span class="stat-label">Reports resolved</span><strong><?= $resolved ?></strong><small><?= $totalReports?round($resolved/$totalReports*100):0 ?>% resolution rate</small></div><div class="stat-card"><div class="stat-icon violet">♡</div><span class="stat-label">Feedback received</span><strong><?= $feedbackCount ?></strong><small>All recorded feedback</small></div></div><div class="analytics-grid"><section class="panel chart-panel"><div class="card-header"><div><div class="eyebrow">Categorized reports</div><h2>Reports by type</h2></div><span class="muted">Filtered count</span></div><div class="bar-chart"><?php foreach($reportTypes as $row): ?><div class="bar-row"><div><span><?= h($row['report_type']) ?></span><strong><?= h($row['total']) ?></strong></div><div class="bar-track"><i style="width:<?= (int)$row['total']/$maxType*100 ?>%"></i></div></div><?php endforeach; ?><?php if(!$reportTypes): ?><p class="empty-state">No reports match the selected filters.</p><?php endif; ?></div></section><section class="panel chart-panel"><div class="card-header"><div><div class="eyebrow">Document demand</div><h2>Requests by document</h2></div><span class="muted">Filtered count</span></div><div class="bar-chart mint-chart"><?php foreach($docTypes as $row): ?><div class="bar-row"><div><span><?= h($row['document_type']) ?></span><strong><?= h($row['total']) ?></strong></div><div class="bar-track"><i style="width:<?= (int)$row['total']/$maxDoc*100 ?>%"></i></div></div><?php endforeach; ?><?php if(!$docTypes): ?><p class="empty-state">No document requests match the selected filters.</p><?php endif; ?></div></section></div><section class="panel chart-panel"><div class="card-header"><div><div class="eyebrow">Status distribution</div><h2>Resolution graph</h2></div><span class="muted">Filtered cases</span></div><div class="status-graph"><?php foreach($statuses as $row): ?><div class="status-column"><div class="status-bar" style="height:<?= $totalReports?(int)$row['total']/$totalReports*150:8 ?>px"></div><strong><?= h($row['total']) ?></strong><span><?= h($row['status']) ?></span></div><?php endforeach; ?><?php if(!$statuses): ?><p class="empty-state">No status data for this range.</p><?php endif; ?></div></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Itemized report</div><h2>Report register</h2></div><span class="muted">Showing <?= count($recent) ?> matching cases</span></div><div class="table-wrap"><table><thead><tr><th>Case no.</th><th>Category / incident</th><th>Complainant</th><th>Location</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td class="mono"><?= h($row['case_no']) ?></td><td><strong><?= h($row['report_type']) ?></strong><small class="cell-subtext"><?= h($row['incident_type']) ?></small></td><td><?= h($row['complainant']) ?></td><td><?= h($row['location']) ?></td><td><span class="status-pill <?= h(strtolower(str_replace(' ','-',$row['status']))) ?>"><i></i><?= h($row['status']) ?></span></td><td class="muted"><?= h(date('M d, Y',strtotime($row['created_at']))) ?></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="6" class="empty-state">No reports match the selected filters.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
